const Database = require('better-sqlite3');
const db = new Database('{{db_path}}');

db.exec(`
  CREATE TABLE IF NOT EXISTS {{table_name}} (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  );
`);

const insert = db.prepare('INSERT INTO {{table_name}} (name) VALUES (?)');
const list = db.prepare('SELECT * FROM {{table_name}} ORDER BY id DESC LIMIT 100');

module.exports = { db, insert, list };
